using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Xml.Serialization;
public class DeviceProfile{public string Model;public string Color="Zilvergrijs";public double Scale=1;public bool Enabled=true;public DeviceProfile(){}public DeviceProfile(string m){Model=m;}}
public class PhoneDeskConfiguration{public DeviceProfile[] Devices=new[]{new DeviceProfile("Samsung S10"),new DeviceProfile("Oppo Find X5 Pro"),new DeviceProfile("Google Pixel 10"),new DeviceProfile("iPad mini Landscape"),new DeviceProfile("iPad mini Portrait")};}
public static class PhoneDeskConfig{
 static System.Collections.Generic.Dictionary<Form,int> slots=new System.Collections.Generic.Dictionary<Form,int>();
 public static void OpenMeter(Form f){int slot;if(!slots.TryGetValue(f,out slot)){MessageBox.Show("Toestelprofiel ontbreekt.");return;}string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Codex Meter 1.4.0","windows","Codex Meter.exe");if(!File.Exists(exe)){MessageBox.Show("CODEX Meter 1.4.0 ontbreekt naast Phone Desk.");return;}try{var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe){Arguments="--phone-desk --slot="+slot+" --settings=\""+PathName+"\"",WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false});process.EnableRaisingEvents=true;process.Exited+=(s,e)=>{if(!f.IsDisposed&&f.IsHandleCreated)try{f.BeginInvoke((Action)(()=>{f.Show();f.Activate();}));}catch{}};f.Hide();if(process.HasExited)f.Show();}catch(Exception e){MessageBox.Show(e.Message,"CODEX Meter openen mislukt");}}
 public static string[] Models={"Samsung S10","Oppo Find X5 Pro","Google Pixel 10","iPad mini Landscape","iPad mini Portrait"},Colors={"Zilvergrijs","Zwart","Lichtblauw","Donkerblauw"},Executables={"Phone Desk I.exe","Phone Desk II.exe","Phone Desk III.exe","Phone Desk iPad Mini Landscape Mode.exe","Phone Desk iPad Mini Portrait.exe"};
 public static string PathName=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phone-desk-settings.xml");
 public static PhoneDeskConfiguration Load(){if(!File.Exists(PathName))return new PhoneDeskConfiguration();using(var s=File.OpenRead(PathName)){var c=(PhoneDeskConfiguration)new XmlSerializer(typeof(PhoneDeskConfiguration)).Deserialize(s);Validate(c);return c;}}
 public static void Validate(PhoneDeskConfiguration c){if(c==null||c.Devices==null||c.Devices.Length!=5)throw new InvalidDataException("Er moeten vijf profielen zijn.");foreach(var p in c.Devices)if(p==null||Array.IndexOf(Models,p.Model)<0||Array.IndexOf(Colors,p.Color)<0||Double.IsNaN(p.Scale)||p.Scale<0.5||p.Scale>1.5)throw new InvalidDataException("Ongeldig toestelprofiel.");}
 public static void Save(PhoneDeskConfiguration c){Validate(c);using(var s=File.Create(PathName+".tmp"))new XmlSerializer(typeof(PhoneDeskConfiguration)).Serialize(s,c);if(File.Exists(PathName))File.Replace(PathName+".tmp",PathName,PathName+".bak");else File.Move(PathName+".tmp",PathName);}
 public static Size SizeFor(string m){switch(m){case "Oppo Find X5 Pro":return new Size(390,800);case "Google Pixel 10":return new Size(370,760);case "iPad mini Landscape":return new Size(720,560);case "iPad mini Portrait":return new Size(560,760);default:return new Size(350,700);}}
 public static void Bind(Form f,int index){slots[f]=index;DateTime last=DateTime.MinValue;Action apply=()=>{var p=Load().Devices[index];f.Text=Path.GetFileNameWithoutExtension(Executables[index])+" — "+p.Model;f.BackColor=p.Color=="Zwart"?Color.FromArgb(17,20,28):p.Color=="Lichtblauw"?Color.LightBlue:p.Color=="Donkerblauw"?Color.FromArgb(35,65,110):Color.Silver;var size=SizeFor(p.Model);var a=Screen.FromControl(f).WorkingArea;double factor=Math.Min(p.Scale,Math.Min((double)a.Width/size.Width,(double)a.Height/size.Height));f.MinimumSize=Size.Empty;f.Size=new Size((int)(size.Width*factor),(int)(size.Height*factor));f.Location=new Point(Math.Max(a.Left,Math.Min(f.Left,a.Right-f.Width)),Math.Max(a.Top,Math.Min(f.Top,a.Bottom-f.Height)));Labels(f,p.Model);f.Invalidate();last=File.Exists(PathName)?File.GetLastWriteTimeUtc(PathName):DateTime.MinValue;};f.Shown+=(s,e)=>{try{apply();}catch(Exception ex){MessageBox.Show(ex.Message,"Instellingen lezen mislukt");}};var t=new Timer{Interval=1000};t.Tick+=(s,e)=>{var stamp=File.Exists(PathName)?File.GetLastWriteTimeUtc(PathName):DateTime.MinValue;if(stamp!=last)try{apply();}catch{t.Stop();}};t.Start();f.FormClosed+=(s,e)=>{t.Dispose();slots.Remove(f);};if(index>=3){var host=f.Controls[0];var b=new Button{Text="CODEX Meter openen",Left=24,Top=110,Width=220,Height=46,BackColor=Color.FromArgb(232,132,35),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};b.Click+=(s,e)=>OpenMeter(f);host.Controls.Add(b);}}
 static void Labels(Control c,string model){foreach(Control x in c.Controls){if(x is Label&&(x.Text.Contains("OPPO")||x.Text.Contains("PIXEL")||x.Text.Contains("iPad mini")||x.Text=="PHONE DESK"))x.Text=model;Labels(x,model);}}
}
